package com.booksyde.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="volumes",schema="public")
public class VolumeEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="manga_id",nullable=false) private UUID mangaId; @Column(nullable=false) private int number; @Column(nullable=false) private String title=""; @Column(name="file_format",nullable=false) private String fileFormat="images"; @Column(name="page_count",nullable=false) private int pageCount; @Column(nullable=false) private boolean published; @Column(name="cover_url") private String coverUrl; @Column(name="source_type") private String sourceType; @Column(name="source_path") private String sourcePath; @Column(name="unit_kind",nullable=false) private String unitKind="volume"; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; protected VolumeEntity(){} public VolumeEntity(UUID mangaId,int number,String title,String fileFormat,int pageCount,boolean published,String coverUrl,String sourceType,String sourcePath,String unitKind){this.mangaId=mangaId;this.number=number;this.title=title;this.fileFormat=fileFormat;this.pageCount=pageCount;this.published=published;this.coverUrl=coverUrl;this.sourceType=sourceType;this.sourcePath=sourcePath;this.unitKind=unitKind;} public UUID getId(){return id;} public UUID getMangaId(){return mangaId;} public int getNumber(){return number;} public String getTitle(){return title;} public String getFileFormat(){return fileFormat;} public int getPageCount(){return pageCount;} public boolean isPublished(){return published;} public String getCoverUrl(){return coverUrl;} public String getSourceType(){return sourceType;} public String getSourcePath(){return sourcePath;} public String getUnitKind(){return unitKind;} public OffsetDateTime getCreatedAt(){return createdAt;} }
